2467	    public List<IntegrazioneDTO> getIntegrazioni(long bandoId, boolean inEsecuzione, long domandaBandoId) {
2468	        List<BandoForm> bandoForms = bandoFormLocalService.getListaBandoFormBando(bandoId);
2469	        List<IntegrazioneDTO> result;
2470	        // Bando bando = bandoLocalService.fetchBando(bandoId);
2471	        // TODO ot
2472	
2473	        Stream<BandoForm> stream;
2474	        if (!inEsecuzione) {
2475	            stream = bandoForms.stream().filter(bandoForm -> bandoForm.getTipoForm().isEmpty() || TipoFormEnum.INTEGRAZIONE.name().equals(bandoForm.getTipoForm()));
2476	        }
2477	        else {
2478	            stream = getBandoFormStreamDaIntegrareByDomandaBandoId(bandoForms, domandaBandoId);
2479	
2480	            // In esecuzione, se è presente il disciplinare esecuzione, il soccorso istruttorio deve essere consentito
2481	            // anche senza un'istanza di servizio esecuzione: si includono i form di integrazione esecuzione
2482	            // (ESECUZIONE_INTEGRAZIONE), tra cui la sottoscrizione del disciplinare.
2483	            boolean disciplinareEsecuzionePresente = bandoForms.stream()
2484	                    .anyMatch(bandoForm -> TipoFormEnum.INTEGRAZIONE_OPERATORE_ESECUZIONE.name().equals(bandoForm.getTipoForm()));
2485	            if (disciplinareEsecuzionePresente) {
2486	                Stream<BandoForm> formIntegrazione = bandoForms.stream()
2487	                        .filter(bandoForm -> TipoFormEnum.ESECUZIONE_INTEGRAZIONE.name().equals(bandoForm.getTipoForm()));
2488	                stream = Stream.concat(stream, formIntegrazione);
2489	            }
2490	        }
2491	
2492	        List<DomandaBandoDatoAggiuntivo> domandaBandoDatoAggiuntivoList = domandaBandoDatoAggiuntivoLocalService.getDomandaBandoDatoAggiuntivoByDomandaBandoIdAndChiave(Collections.singletonList(domandaBandoId), Collections.singletonList("FORM_ESECUZIONE_NON_ABILITATO"));
2493	        Set<String> formDaEscludere = new HashSet<>();
2494	
2495	        if (ListUtil.isNotNull(domandaBandoDatoAggiuntivoList) && ListUtil.isNotEmpty(domandaBandoDatoAggiuntivoList)) {
2496	            formDaEscludere = domandaBandoDatoAggiuntivoList.stream().map(DomandaBandoDatoAggiuntivo::getValore).collect(Collectors.toSet());
2497	        }
2498	
2499	        if (Validator.isNotNull(formDaEscludere) && !formDaEscludere.isEmpty()) {
2500	            Set<String> finalFormDaEscludere = formDaEscludere;
2501	            result = stream.map(bandoForm -> formLocalService.fetchForm(bandoForm.getFormId()))
2502	                    .filter(form -> !form.isPrincipale())
2503	                    .filter(form -> !finalFormDaEscludere.contains(form.getCodice()))
2504	                    .map(this::mapForm).collect(Collectors.toList());
2505	
2506	        } else {
2507	            result = stream.map(bandoForm -> formLocalService.fetchForm(bandoForm.getFormId()))
2508	                    .filter(form -> !form.isPrincipale())
2509	                    .map(this::mapForm).collect(Collectors.toList());
2510	        }
2511	
2512	        // Il cascade stream e il gating del disciplinare possono proporre lo stesso ESECUZIONE_INTEGRAZIONE:
2513	        // si rimuovono i duplicati per formId mantenendo l'ordine.
2514	        Set<Long> formIdGiaPresenti = new HashSet<>();
2515	        List<IntegrazioneDTO> integrazioniSenzaDuplicati = new ArrayList<>();
2516	        for (IntegrazioneDTO integrazione : result) {
2517	            if (formIdGiaPresenti.add(integrazione.getId())) {
2518	                integrazioniSenzaDuplicati.add(integrazione);
2519	            }
2520	        }
2521	        return integrazioniSenzaDuplicati;
2522	    }
