private Stream<BandoForm> getBandoFormStreamDaIntegrareByDomandaBandoId(
        List<BandoForm> bandoForms, long domandaBandoId) {

    // Recupero tutte le istanze della domanda
    List<IstanzaDomandaBando> istanze = istanzaDomandaBandoLocalService
            .getIstanzeDomandeBandoByDomandaBandoId(domandaBandoId);

    // Mappa: formId → ultima istanza (per createDate, poi id per tie-break)
    Map<Long, IstanzaDomandaBando> ultimaIstanzaPerForm = istanze.stream()
            .collect(Collectors.toMap(
                    IstanzaDomandaBando::getFormId,
                    i -> i,
                    (i1, i2) -> {
                        int cmp = i1.getCreateDate().compareTo(i2.getCreateDate());
                        return (cmp > 0 || (cmp == 0 && i1.getIstanzaDomandaBandoId() > i2.getIstanzaDomandaBandoId()))
                                ? i1 : i2;
                    }
            ));

    //Preload Form per evitare N+1
    Map<Long, Form> formMap = bandoForms.stream()
            .map(BandoForm::getFormId)
            .distinct()
            .map(formLocalService::fetchForm)
            .filter(Objects::nonNull)
            .collect(Collectors.toMap(Form::getFormId, f -> f));

    Set<String> codiciFormDaMostrare = new HashSet<>();

    List<BandoForm> bandoFormsInEsecuzione = bandoForms.stream()
            .filter(bf -> TipoFormEnum.ESECUZIONE.name().equals(bf.getTipoForm()))
            .collect(Collectors.toList());

    // Itero solo i BandoForm di tipo ESECUZIONE
    for (BandoForm bandoForm : bandoFormsInEsecuzione) {

        IstanzaDomandaBando ultimaIstanza = ultimaIstanzaPerForm.get(bandoForm.getFormId());

        // Nessuna istanza → ESCLUDI
        if (ultimaIstanza == null) {
            continue;
        }

        // Stato non valido → ESCLUDI
        if (!"INTEGRATA".equals(ultimaIstanza.getStato()) &&
                !"CONFERMATA".equals(ultimaIstanza.getStato())) {
            continue;
        }

        Form form = formMap.get(bandoForm.getFormId());

        if (form != null) {
            String codice = getFormIntegrazioneEsecuzione(form, ultimaIstanza);

            // Se c'è formDaMostrare → includi
            if (Validator.isNotNull(codice)) {
                codiciFormDaMostrare.add(codice);
            }
        }
    }

    // Filtro finale: ritorna solo i BandoForm i cui form hanno codice valido
    return bandoForms.stream()
            .filter(bf -> {
                Form form = formMap.get(bf.getFormId());
                return form != null && codiciFormDaMostrare.contains(form.getCodice());
            });
}

private HashMap<String, String> getFormInformation(Form form, IstanzaDomandaBando istanzaDomandaBando) {
    HashMap<String, String> response = new HashMap<>();

    // Un'istanza non ancora compilata ha json nullo: non contiene custom field da cui ricavare
    // formAttuale/formDaMostrare, quindi non concorre alla cascata di integrazione.
    if (istanzaDomandaBando == null || Validator.isNull(istanzaDomandaBando.getJson())) {
        return response;
    }

    List<FormField> listaField = new ArrayList<>();

    Set<Option> jsonPathOptions = new HashSet<Option>();
    jsonPathOptions.add(Option.SUPPRESS_EXCEPTIONS);
    jsonPathOptions.add(Option.ALWAYS_RETURN_LIST);

    Configuration jsonPathConfiguration = Configuration.builder()
            .jsonProvider(new JacksonJsonNodeJsonProvider()).mappingProvider(new JacksonMappingProvider())
            .options(jsonPathOptions).build();
    JsonObject formObject = new JsonParser().parse(istanzaDomandaBando.getJson()).getAsJsonObject();
    if (Validator.isNotNull(formObject) && formObject.has("alpaca")) {
        String jsonForm = formObject.get("alpaca").toString();
        listaField = JsonPathUtil.getFormFields(jsonForm, typesCustomFormEsecuzione);
    }
    JsonNode fieldOptions = null;

    if (Validator.isNotNull(listaField) && !listaField.isEmpty()) {
        for (FormField campo : listaField) {
            String field = campo.getPath().substring(campo.getPath().indexOf(".") + 1);
            String[] splitFields = field.split("(?<=\\])(?=\\[)");
            String jsonPathOptionsField = ALPACA_OPTIONS_FIELD + ALPACA_FIELDS_FIELD + splitFields[0] + ALPACA_FIELDS_FIELD + splitFields[1];
            fieldOptions = JsonPath.using(jsonPathConfiguration).parse(form.getJson()).read(jsonPathOptionsField);
            if (Validator.isNotNull(fieldOptions) && !fieldOptions.isEmpty()) {
                JsonNode options = fieldOptions.get(0);
                String formAttuale = null;
                String formDaMostrare = null;
                if (options.has("formAttuale")) {
                    formAttuale = options.get("formAttuale").asText();
                }

                if (options.has("formDaMostrare")) {
                    formDaMostrare = options.get("formDaMostrare").asText();
                }

                if (Validator.isNotNull(formDaMostrare) && Validator.isNotNull(formAttuale)) {
                    response.put(formAttuale, formDaMostrare);
                }
            }
        }
    }

    return response;
}

