                if (options.has("formDaMostrare")) {
                    response = options.get("formDaMostrare").asText();
                }
            }
        }
    }
    return response;
}

/**
 * Verifica se il form di integrazione associato al BandoForm è gestito dalla cascata, cioè è agganciato a un form
 * ESECUZIONE tramite formAttuale/formDaMostrare. In tal caso non deve essere proposto dal ramo del disciplinare,
 * perché resta subordinato alla compilazione del cittadino.
 */
private boolean isFormIntegrazioneCascade(BandoForm bandoForm, Set<String> codiciIntegrazioneCascade) {
    Form form = formLocalService.fetchForm(bandoForm.getFormId());
    return form != null && codiciIntegrazioneCascade.contains(form.getCodice());
}

/**
 * Raccoglie i codici dei form di integrazione esecuzione dichiarati come formDaMostrare nelle definizioni dei form
 * ESECUZIONE del bando. La lettura è fatta sulla definizione del form, quindi è indipendente dalle istanze del
 * cittadino e descrive l'aggancio a livello di configurazione.
 */
private Set<String> getCodiciIntegrazioneEsecuzioneCascade(List<BandoForm> bandoForms) {
    Set<String> codici = new HashSet<>();

    for (BandoForm bandoForm : bandoForms) {
        if (!TipoFormEnum.ESECUZIONE.name().equals(bandoForm.getTipoForm())) {
            continue;
        }

        Form form = formLocalService.fetchForm(bandoForm.getFormId());
        if (form == null || Validator.isNull(form.getJson())) {
            continue;
        }

        codici.addAll(getCodiciFormDaMostrare(form));
    }

    return codici;
}

/**
 * Estrae dalla definizione di un form ESECUZIONE tutti i codici di integrazione referenziati come formDaMostrare
 * nei custom field di tipo customFormEsecuzione.
 */
private Set<String> getCodiciFormDaMostrare(Form form) {
    Set<String> codici = new HashSet<>();

    List<FormField> listaField = JsonPathUtil.getFormFields(form.getJson(), typesCustomFormEsecuzione);
    if (listaField == null || listaField.isEmpty()) {
        return codici;
    }

    Set<Option> jsonPathOptions = new HashSet<Option>();
    jsonPathOptions.add(Option.SUPPRESS_EXCEPTIONS);
    jsonPathOptions.add(Option.ALWAYS_RETURN_LIST);

    Configuration jsonPathConfiguration = Configuration.builder()
            .jsonProvider(new JacksonJsonNodeJsonProvider()).mappingProvider(new JacksonMappingProvider())
            .options(jsonPathOptions).build();

    for (FormField campo : listaField) {
        String field = campo.getPath().substring(campo.getPath().indexOf(".") + 1);
        String[] splitFields = field.split("(?<=\\])(?=\\[)");
        String jsonPathOptionsField = ALPACA_OPTIONS_FIELD + ALPACA_FIELDS_FIELD + splitFields[0] + ALPACA_FIELDS_FIELD + splitFields[1];
        JsonNode fieldOptions = JsonPath.using(jsonPathConfiguration).parse(form.getJson()).read(jsonPathOptionsField);
        if (Validator.isNotNull(fieldOptions) && !fieldOptions.isEmpty()) {
            JsonNode options = fieldOptions.get(0);
            if (options.has("formDaMostrare")) {
                String codice = options.get("formDaMostrare").asText();
                if (Validator.isNotNull(codice)) {
                    codici.add(codice);
                }
            }
        }
    }

    return codici;
}

