package it.servizidigitali.gestionebandi.common.enumeration;

import java.util.ArrayList;
import java.util.List;

public enum TipoFormEnum {

    ESECUZIONE(true, false),
    ESECUZIONE_CRONOPROGRAMMA(true, false),
    INTEGRAZIONE(false, true),
    ANNULLAMENTO(false, false),
    ESECUZIONE_ANTICIPO(true, false),
    ESECUZIONE_SALDO(true, false),
    ESECUZIONE_RINUNCIA(true, false),
    ESECUZIONE_ANTICIPO_INTEGRAZIONE(false, true),
    ESECUZIONE_SALDO_INTEGRAZIONE(false, true),
    QUESTIONARIO(false, true),
    INTEGRAZIONE_OPERATORE(false, false),
    INTEGRAZIONE_OPERATORE_ESECUZIONE(false, false),
    INTEGRAZIONE_FRONTEND(false, false),
    ESECUZIONE_PRIMO_ANTICIPO(true, false),
    ESECUZIONE_SECONDO_ANTICIPO(true, false),
    ESECUZIONE_INTEGRAZIONE(false, false),
    ESECUZIONE_INTEGRAZIONE_DISCIPLINARE(false, false);

    private final boolean isEsecuzione;
    private final boolean isIntegrazione;

    TipoFormEnum(boolean isEsecuzione, boolean isIntegrazione) {
        this.isEsecuzione = isEsecuzione;
        this.isIntegrazione = isIntegrazione;
    }

    public boolean isEsecuzione() {
        return isEsecuzione;
    }
    public boolean isIntegrazione() {
        return isIntegrazione;
    }

    public static List<TipoFormEnum> getTipoFormEsecuzione() {
        List<TipoFormEnum> result = new ArrayList<>();
        for(TipoFormEnum tipoFormEnum: TipoFormEnum.values()) {
            if (tipoFormEnum.isEsecuzione()) {
                result.add(tipoFormEnum);
            }
        }
        return result;
    }
    public static List<TipoFormEnum> getTipoFormIntegrazione() {
        List<TipoFormEnum> result = new ArrayList<>();
        for(TipoFormEnum tipoFormEnum: TipoFormEnum.values()) {
            if (tipoFormEnum.isIntegrazione()) {
                result.add(tipoFormEnum);
            }
        }
        return result;
    }
}

